-- 3. Guard: fail loudly if any row escaped classification.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM food_items WHERE is_veg IS NULL) THEN
  RAISE EXCEPTION 'diet backfill incomplete: NULL is_veg rows remain'; END IF; END $$;

-- 4. Enforce non-null going forward (new rows must state diet).
-- DEFAULT true retained: vendor/admin inserts omitting is_veg stay
-- veg-biased; the vendor menu diet toggle covers corrections. A
-- stricter future step is dropping the default once all writers
-- set is_veg explicitly.
ALTER TABLE food_items ALTER COLUMN is_veg SET NOT NULL;
